import{_ as e,c as o,o as i,ag as r}from"./chunks/framework.Bw-5EFTY.js";const d=JSON.parse('{"title":"How to Get Support","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting-and-support/how-to-get-support.md","filePath":"guide/troubleshooting-and-support/how-to-get-support.md","lastUpdated":1752486742000}'),s={name:"guide/troubleshooting-and-support/how-to-get-support.md"};function a(n,t,p,l,u,c){return i(),o("div",null,t[0]||(t[0]=[r('<h1 id="how-to-get-support" tabindex="-1">How to Get Support <a class="header-anchor" href="#how-to-get-support" aria-label="Permalink to &quot;How to Get Support&quot;">​</a></h1><p>If you have reviewed our documentation and are still encountering a problem with FluentAffiliate, our dedicated support team at WPManageNinja is here to help.</p><h3 id="how-to-contact-support" tabindex="-1">How to Contact Support <a class="header-anchor" href="#how-to-contact-support" aria-label="Permalink to &quot;How to Contact Support&quot;">​</a></h3><p>To ensure you receive the quickest and most effective assistance, please follow these guidelines when contacting us:</p><ol><li><p><strong>Visit the WPManageNinja Support Portal:</strong> Go to the official <a href="https://wpmanageninja.com/support-tickets/" target="_blank" rel="noreferrer">WPManageNinja support website</a>. This is the primary channel for submitting support tickets.</p></li><li><p><strong>Submit a Support Ticket:</strong></p><ul><li>Log in to your WPManageNinja account.</li><li>Navigate to the &quot;Support Tickets&quot; section.</li><li>Click on &quot;Create a New Ticket.&quot;</li></ul></li><li><p><strong>Provide Detailed Information:</strong> When submitting your ticket, please include as much detail as possible. This helps our team understand your issue quickly and provide a precise solution. Include:</p><ul><li><strong>Your FluentAffiliate License Key:</strong> This helps us verify your purchase and provide premium support.</li><li><strong>A Clear Description of the Problem:</strong> Explain what you are trying to achieve and what is happening instead.</li><li><strong>Steps to Reproduce:</strong> List the exact steps you take that lead to the issue.</li><li><strong>Screenshots or Screen Recordings:</strong> Visual aids are incredibly helpful for diagnosing problems.</li><li><strong>Error Messages:</strong> If you see any error messages, please copy and paste them into the ticket.</li><li><strong>Your WordPress Version.</strong></li><li><strong>Your FluentAffiliate Plugin Version.</strong></li><li><strong>Any Other Plugins Active on Your Site:</strong> List them, especially if they are related to e-commerce, memberships, or forms that you have integrated with FluentAffiliate.</li></ul></li></ol><p><strong>Support Hours:</strong> Our support team operates during business hours, typically Monday to Friday. We strive to respond to all inquiries as quickly as possible.</p><p>We are committed to helping you succeed with FluentAffiliate!</p>',7)]))}const g=e(s,[["render",a]]);export{d as __pageData,g as default};
